package com.example.hazardreporting.data.incident.entity

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Room row of the `incident_photos` table: one photo of an incident. A photo has a local file until it is
 * uploaded and a server URL once it is. The file is deleted right after the upload, but its path stays,
 * so an edit saved from a form opened before the upload can still be matched to the uploaded photo
 *
 * @property id id of the row, generated by Room
 * @property incidentLocalId local id of the incident the photo belongs to; deleting the incident deletes its photos
 * @property position index of the photo among the incident's photos
 * @property localPath absolute path of the file the photo was taken or imported as, or null if it came from the
 * server; once [remoteUrl] is set, the file no longer exists
 * @property remoteUrl the photo's URL as the server sends it, e.g. `"/uploads/ab12.jpg"`, or null until uploaded
 *
 * @author Roman Pliskin on 29.10.2026
 */
@Entity(
    tableName = "incident_photos",
    foreignKeys = [
        ForeignKey(
            entity = IncidentEntity::class,
            parentColumns = ["localId"],
            childColumns = ["incidentLocalId"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
    indices = [Index(value = ["incidentLocalId"])],
)
data class IncidentPhotoEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val incidentLocalId: Long,
    val position: Int,
    val localPath: String?,
    val remoteUrl: String?,
)
